17	package org.springframework.boot.context.config;
18	
19	import java.util.ArrayList;
20	import java.util.Collections;
21	import java.util.List;
22	import java.util.function.Supplier;
23	
24	import org.apache.commons.logging.Log;
25	import org.jspecify.annotations.Nullable;
26	
27	import org.springframework.boot.bootstrap.BootstrapContext;
28	import org.springframework.boot.bootstrap.BootstrapRegistry;
29	import org.springframework.boot.bootstrap.ConfigurableBootstrapContext;
30	import org.springframework.boot.context.properties.bind.Binder;
31	import org.springframework.boot.logging.DeferredLogFactory;
32	import org.springframework.core.env.Environment;
33	import org.springframework.core.io.ResourceLoader;
34	import org.springframework.core.io.support.SpringFactoriesLoader;
35	import org.springframework.core.io.support.SpringFactoriesLoader.ArgumentResolver;
36	
37	/**
38	 * A collection of {@link ConfigDataLocationResolver} instances loaded via
39	 * {@code spring.factories}.
40	 *
41	 * @author Phillip Webb
42	 * @author Madhura Bhave
43	 */
44	class ConfigDataLocationResolvers {
45	
46		private final List<ConfigDataLocationResolver<?>> resolvers;
47	
48		/**
49		 * Create a new {@link ConfigDataLocationResolvers} instance.
50		 * @param logFactory a {@link DeferredLogFactory} used to inject {@link Log} instances
51		 * @param bootstrapContext the bootstrap context
52		 * @param binder a binder providing values from the initial {@link Environment}
53		 * @param resourceLoader {@link ResourceLoader} to load resource locations
54		 * @param springFactoriesLoader to load {@link ConfigDataLocationResolver} instances
55		 */
56		ConfigDataLocationResolvers(DeferredLogFactory logFactory, ConfigurableBootstrapContext bootstrapContext,
57				Binder binder, ResourceLoader resourceLoader, SpringFactoriesLoader springFactoriesLoader) {
58			ArgumentResolver argumentResolver = ArgumentResolver.of(DeferredLogFactory.class, logFactory);
59			argumentResolver = argumentResolver.and(Binder.class, binder);
60			argumentResolver = argumentResolver.and(ResourceLoader.class, resourceLoader);
61			argumentResolver = argumentResolver.and(ConfigurableBootstrapContext.class, bootstrapContext);
62			argumentResolver = argumentResolver.and(BootstrapContext.class, bootstrapContext);
63			argumentResolver = argumentResolver.and(BootstrapRegistry.class, bootstrapContext);
64			argumentResolver = argumentResolver.andSupplied(Log.class, () -> {
65				throw new IllegalArgumentException("Log types cannot be injected, please use DeferredLogFactory");
66			});
67			this.resolvers = reorder(springFactoriesLoader.load(ConfigDataLocationResolver.class, argumentResolver));
68		}
69	
70		@SuppressWarnings("rawtypes")
71		private List<ConfigDataLocationResolver<?>> reorder(List<ConfigDataLocationResolver> resolvers) {
72			List<ConfigDataLocationResolver<?>> reordered = new ArrayList<>(resolvers.size());
73			ConfigDataLocationResolver<?> standardConfigDataLocationResolver = null;
74			for (ConfigDataLocationResolver<?> resolver : resolvers) {
75				if (resolver instanceof StandardConfigDataLocationResolver) {
76					standardConfigDataLocationResolver = resolver;
77				}
78				else {
79					reordered.add(resolver);
80				}
81			}
82			if (standardConfigDataLocationResolver != null) {
83				reordered.add(standardConfigDataLocationResolver);
84			}
85			return Collections.unmodifiableList(reordered);
86		}
87	
88		List<ConfigDataResolutionResult> resolve(ConfigDataLocationResolverContext context,
89				@Nullable ConfigDataLocation location, @Nullable Profiles profiles) {
90			if (location == null) {
91				return Collections.emptyList();
92			}
93			for (ConfigDataLocationResolver<?> resolver : getResolvers()) {
94				if (resolver.isResolvable(context, location)) {
95					return resolve(resolver, context, location, profiles);
96				}
97			}
98			throw new UnsupportedConfigDataLocationException(location);
99		}
100	
101		private List<ConfigDataResolutionResult> resolve(ConfigDataLocationResolver<?> resolver,
102				ConfigDataLocationResolverContext context, ConfigDataLocation location, @Nullable Profiles profiles) {
103			List<ConfigDataResolutionResult> resolved = resolve(location, false, () -> resolver.resolve(context, location));
104			if (profiles == null) {
105				return resolved;
106			}
107			List<ConfigDataResolutionResult> profileSpecific = resolve(location, true,
108					() -> resolver.resolveProfileSpecific(context, location, profiles));
109			return merge(resolved, profileSpecific);
110		}
111	
112		private List<ConfigDataResolutionResult> resolve(ConfigDataLocation location, boolean profileSpecific,
113				Supplier<List<? extends ConfigDataResource>> resolveAction) {
114			List<ConfigDataResource> resources = nonNullList(resolveAction.get());
115			List<ConfigDataResolutionResult> resolved = new ArrayList<>(resources.size());
116			for (ConfigDataResource resource : resources) {
117				resolved.add(new ConfigDataResolutionResult(location, resource, profileSpecific));
118			}
119			return resolved;
120		}
121	
122		@SuppressWarnings("unchecked")
123		private <T> List<T> nonNullList(@Nullable List<? extends T> list) {
124			return (list != null) ? (List<T>) list : Collections.emptyList();
125		}
126	
127		private <T> List<T> merge(List<T> list1, List<T> list2) {
128			List<T> merged = new ArrayList<>(list1.size() + list2.size());
129			merged.addAll(list1);
130			merged.addAll(list2);
131			return merged;
132		}
133	
134		/**
135		 * Return the resolvers managed by this object.
136		 * @return the resolvers
137		 */
138		List<ConfigDataLocationResolver<?>> getResolvers() {
139			return this.resolvers;
140		}
141	
142	}
