17	package org.springframework.boot.context.properties.bind;
18	
19	import java.util.function.Supplier;
20	
21	import org.jspecify.annotations.Nullable;
22	
23	import org.springframework.boot.context.properties.bind.Binder.Context;
24	import org.springframework.boot.context.properties.source.ConfigurationPropertyName;
25	import org.springframework.boot.context.properties.source.ConfigurationPropertySource;
26	
27	/**
28	 * Internal strategy used by {@link Binder} to bind aggregates (Maps, Lists, Arrays).
29	 *
30	 * @param <T> the type being bound
31	 * @author Phillip Webb
32	 * @author Madhura Bhave
33	 */
34	abstract class AggregateBinder<T> {
35	
36		private final Context context;
37	
38		AggregateBinder(Context context) {
39			this.context = context;
40		}
41	
42		/**
43		 * Determine if recursive binding is supported.
44		 * @param source the configuration property source or {@code null} for all sources.
45		 * @return if recursive binding is supported
46		 */
47		protected abstract boolean isAllowRecursiveBinding(@Nullable ConfigurationPropertySource source);
48	
49		/**
50		 * Perform binding for the aggregate.
51		 * @param name the configuration property name to bind
52		 * @param target the target to bind
53		 * @param elementBinder an element binder
54		 * @return the bound aggregate or null
55		 */
56		@SuppressWarnings("unchecked")
57		final @Nullable Object bind(ConfigurationPropertyName name, Bindable<?> target,
58				AggregateElementBinder elementBinder) {
59			Object result = bindAggregate(name, target, elementBinder);
60			Supplier<?> value = target.getValue();
61			if (result == null || value == null) {
62				return result;
63			}
64			return merge((Supplier<T>) value, (T) result);
65		}
66	
67		/**
68		 * Perform the actual aggregate binding.
69		 * @param name the configuration property name to bind
70		 * @param target the target to bind
71		 * @param elementBinder an element binder
72		 * @return the bound result
73		 */
74		protected abstract @Nullable Object bindAggregate(ConfigurationPropertyName name, Bindable<?> target,
75				AggregateElementBinder elementBinder);
76	
77		/**
78		 * Merge any additional elements into the existing aggregate.
79		 * @param existing the supplier for the existing value
80		 * @param additional the additional elements to merge
81		 * @return the merged result
82		 */
83		protected abstract T merge(Supplier<T> existing, T additional);
84	
85		/**
86		 * Return the context being used by this binder.
87		 * @return the context
88		 */
89		protected final Context getContext() {
90			return this.context;
91		}
92	
93		/**
94		 * Internal class used to supply the aggregate and cache the value.
95		 *
96		 * @param <T> the aggregate type
97		 */
98		protected static class AggregateSupplier<T> {
99	
100			private final Supplier<T> supplier;
101	
102			private @Nullable T supplied;
103	
104			public AggregateSupplier(Supplier<T> supplier) {
105				this.supplier = supplier;
106			}
107	
108			public T get() {
109				if (this.supplied == null) {
110					this.supplied = this.supplier.get();
111				}
112				return this.supplied;
113			}
114	
115			public boolean wasSupplied() {
116				return this.supplied != null;
117			}
118	
119		}
120	
121	}
