62	/**
63	 * A {@link WebApplicationContext} that can be used to bootstrap itself from a contained
64	 * {@link ServletWebServerFactory} bean.
65	 * <p>
66	 * This context will create, initialize and run an {@link WebServer} by searching for a
67	 * single {@link ServletWebServerFactory} bean within the {@link ApplicationContext}
68	 * itself. The {@link ServletWebServerFactory} is free to use standard Spring concepts
69	 * (such as dependency injection, lifecycle callbacks and property placeholder variables).
70	 * <p>
71	 * In addition, any {@link Servlet} or {@link Filter} beans defined in the context will be
72	 * automatically registered with the web server. In the case of a single Servlet bean, the
73	 * '/' mapping will be used. If multiple Servlet beans are found then the lowercase bean
74	 * name will be used as a mapping prefix. Any Servlet named 'dispatcherServlet' will
75	 * always be mapped to '/'. Filter beans will be mapped to all URLs ('/*').
76	 * <p>
77	 * For more advanced configuration, the context can instead define beans that implement
78	 * the {@link ServletContextInitializer} interface (most often
79	 * {@link ServletRegistrationBean}s and/or {@link FilterRegistrationBean}s). To prevent
80	 * double registration, the use of {@link ServletContextInitializer} beans will disable
81	 * automatic Servlet and Filter bean registration.
82	 * <p>
83	 * Although this context can be used directly, most developers should consider using the
84	 * {@link AnnotationConfigServletWebServerApplicationContext} or
85	 * {@link XmlServletWebServerApplicationContext} variants.
86	 *
87	 * @author Phillip Webb
88	 * @author Dave Syer
89	 * @author Scott Frederick
90	 * @since 4.0.0
91	 * @see AnnotationConfigServletWebServerApplicationContext
92	 * @see XmlServletWebServerApplicationContext
93	 * @see ServletWebServerFactory
94	 */
95	public class ServletWebServerApplicationContext extends GenericWebApplicationContext
96			implements ConfigurableWebServerApplicationContext {
97	
98		private static final Log logger = LogFactory.getLog(ServletWebServerApplicationContext.class);
99	
100		/**
101		 * Constant value for the DispatcherServlet bean name. A Servlet bean with this name
102		 * is deemed to be the "main" servlet and is automatically given a mapping of "/" by
103		 * default. To change the default behavior you can use a
104		 * {@link ServletRegistrationBean} or a different bean name.
105		 */
106		public static final String DISPATCHER_SERVLET_NAME = "dispatcherServlet";
107	
108		private volatile @Nullable WebServer webServer;
109	
110		private @Nullable ServletConfig servletConfig;
111	
112		private @Nullable String serverNamespace;
113	
114		/**
115		 * Create a new {@link ServletWebServerApplicationContext}.
116		 */
117		public ServletWebServerApplicationContext() {
118		}
119	
120		/**
121		 * Create a new {@link ServletWebServerApplicationContext} with the given
122		 * {@code DefaultListableBeanFactory}.
123		 * @param beanFactory the DefaultListableBeanFactory instance to use for this context
124		 */
125		public ServletWebServerApplicationContext(DefaultListableBeanFactory beanFactory) {
126			super(beanFactory);
127		}
128	
129		/**
130		 * Register ServletContextAwareProcessor.
131		 * @see ServletContextAwareProcessor
132		 */
133		@Override
134		protected void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) {
135			beanFactory.addBeanPostProcessor(new WebApplicationContextServletContextAwareProcessor(this));
136			beanFactory.ignoreDependencyInterface(ServletContextAware.class);
137			registerWebApplicationScopes();
138		}
139	
140		@Override
141		public final void refresh() throws BeansException, IllegalStateException {
142			try {
143				super.refresh();
144			}
145			catch (RuntimeException ex) {
146				WebServer webServer = this.webServer;
147				if (webServer != null) {
148					try {
149						webServer.stop();
150						webServer.destroy();
151					}
152					catch (RuntimeException stopOrDestroyEx) {
153						ex.addSuppressed(stopOrDestroyEx);
154					}
155				}
156				throw ex;
157			}
158		}
159	
160		@Override
161		protected void onRefresh() {
162			super.onRefresh();
163			try {
164				createWebServer();
165			}
166			catch (Throwable ex) {
167				throw new ApplicationContextException("Unable to start web server", ex);
168			}
169		}
170	
171		@Override
172		protected void doClose() {
173			if (isActive()) {
174				AvailabilityChangeEvent.publish(this, ReadinessState.REFUSING_TRAFFIC);
175			}
176			super.doClose();
177			WebServer webServer = this.webServer;
178			if (webServer != null) {
179				webServer.destroy();
180			}
181		}
182	
183		private void createWebServer() {
184			WebServer webServer = this.webServer;
185			ServletContext servletContext = getServletContext();
186			if (webServer == null && servletContext == null) {
187				StartupStep createWebServer = getApplicationStartup().start("spring.boot.webserver.create");
188				ServletWebServerFactory factory = getWebServerFactory();
189				createWebServer.tag("factory", factory.getClass().toString());
190				webServer = factory.getWebServer(getSelfInitializer());
191				this.webServer = webServer;
192				createWebServer.end();
193				getBeanFactory().registerSingleton("webServerGracefulShutdown",
194						new WebServerGracefulShutdownLifecycle(webServer));
195				getBeanFactory().registerSingleton("webServerStartStop", new WebServerStartStopLifecycle(this, webServer));
196			}
197			else if (servletContext != null) {
198				try {
199					getSelfInitializer().onStartup(servletContext);
200				}
201				catch (ServletException ex) {
202					throw new ApplicationContextException("Cannot initialize servlet context", ex);
203				}
204			}
205			initPropertySources();
206		}
207	
208		/**
209		 * Returns the {@link ServletWebServerFactory} that should be used to create the
210		 * embedded {@link WebServer}. By default this method searches for a suitable bean in
211		 * the context itself.
212		 * @return a {@link ServletWebServerFactory} (never {@code null})
213		 */
214		protected ServletWebServerFactory getWebServerFactory() {
215			// Use bean names so that we don't consider the hierarchy
216			String[] beanNames = getBeanFactory().getBeanNamesForType(ServletWebServerFactory.class);
217			if (beanNames.length == 0) {
218				throw new MissingWebServerFactoryBeanException(getClass(), ServletWebServerFactory.class,
219						WebApplicationType.SERVLET);
220			}
221			if (beanNames.length > 1) {
222				throw new ApplicationContextException("Unable to start ServletWebServerApplicationContext due to multiple "
223						+ "ServletWebServerFactory beans : " + StringUtils.arrayToCommaDelimitedString(beanNames));
224			}
225			return getBeanFactory().getBean(beanNames[0], ServletWebServerFactory.class);
226		}
227	
228		/**
229		 * Returns the {@link ServletContextInitializer} that will be used to complete the
230		 * setup of this {@link WebApplicationContext}.
231		 * @return the self initializer
232		 * @see #prepareWebApplicationContext(ServletContext)
233		 */
234		private org.springframework.boot.web.servlet.ServletContextInitializer getSelfInitializer() {
235			return new WebApplicationContextInitializer(this)::initialize;
236		}
237	
238		private void registerWebApplicationScopes() {
239			ExistingWebApplicationScopes existingScopes = new ExistingWebApplicationScopes(getBeanFactory());
240			WebApplicationContextUtils.registerWebApplicationScopes(getBeanFactory());
241			existingScopes.restore();
242		}
243	
244		@Override
245		protected Resource getResourceByPath(String path) {
246			if (getServletContext() == null) {
247				return new ClassPathContextResource(path, getClassLoader());
248			}
249			return new ServletContextResource(getServletContext(), path);
250		}
251	
252		@Override
253		public @Nullable String getServerNamespace() {
254			return this.serverNamespace;
255		}
256	
257		@Override
258		public void setServerNamespace(@Nullable String serverNamespace) {
259			this.serverNamespace = serverNamespace;
260		}
261	
262		@Override
263		public void setServletConfig(@Nullable ServletConfig servletConfig) {
264			this.servletConfig = servletConfig;
265		}
266	
267		@Override
268		public @Nullable ServletConfig getServletConfig() {
269			return this.servletConfig;
270		}
271	
272		/**
273		 * Returns the {@link WebServer} that was created by the context or {@code null} if
274		 * the server has not yet been created.
275		 * @return the embedded web server
276		 */
277		@Override
278		public @Nullable WebServer getWebServer() {
279			return this.webServer;
280		}
281	
282		/**
283		 * Utility class to store and restore any user defined scopes. This allows scopes to
284		 * be registered in an ApplicationContextInitializer in the same way as they would in
285		 * a classic non-embedded web application context.
286		 */
287		public static class ExistingWebApplicationScopes {
288	
289			private static final Set<String> SCOPES;
290	
291			static {
292				Set<String> scopes = new LinkedHashSet<>();
293				scopes.add(WebApplicationContext.SCOPE_REQUEST);
294				scopes.add(WebApplicationContext.SCOPE_SESSION);
295				SCOPES = Collections.unmodifiableSet(scopes);
296			}
297	
298			private final ConfigurableListableBeanFactory beanFactory;
299	
300			private final Map<String, Scope> scopes = new HashMap<>();
301	
302			public ExistingWebApplicationScopes(ConfigurableListableBeanFactory beanFactory) {
303				this.beanFactory = beanFactory;
304				for (String scopeName : SCOPES) {
305					Scope scope = beanFactory.getRegisteredScope(scopeName);
306					if (scope != null) {
307						this.scopes.put(scopeName, scope);
308					}
309				}
310			}
311	
312			public void restore() {
313				this.scopes.forEach((key, value) -> {
314					if (logger.isInfoEnabled()) {
315						logger.info("Restoring user defined scope " + key);
316					}
317					this.beanFactory.registerScope(key, value);
318				});
319			}
320	
321		}
322	
323	}
