17	package org.springframework.boot.context.properties.source;
18	
19	import org.jspecify.annotations.Nullable;
20	
21	import org.springframework.boot.origin.Origin;
22	import org.springframework.boot.origin.OriginLookup;
23	import org.springframework.core.env.Environment;
24	import org.springframework.core.env.PropertyResolver;
25	import org.springframework.core.env.PropertySource;
26	
27	/**
28	 * {@link PropertySource} that exposes {@link ConfigurationPropertySource} instances so
29	 * that they can be used with a {@link PropertyResolver} or added to the
30	 * {@link Environment}.
31	 *
32	 * @author Phillip Webb
33	 * @author Madhura Bhave
34	 */
35	class ConfigurationPropertySourcesPropertySource extends PropertySource<Iterable<ConfigurationPropertySource>>
36			implements OriginLookup<String> {
37	
38		ConfigurationPropertySourcesPropertySource(String name, Iterable<ConfigurationPropertySource> source) {
39			super(name, source);
40		}
41	
42		@Override
43		public boolean containsProperty(String name) {
44			return findConfigurationProperty(name) != null;
45		}
46	
47		@Override
48		public @Nullable Object getProperty(String name) {
49			ConfigurationProperty configurationProperty = findConfigurationProperty(name);
50			return (configurationProperty != null) ? configurationProperty.getValue() : null;
51		}
52	
53		@Override
54		public @Nullable Origin getOrigin(String name) {
55			return Origin.from(findConfigurationProperty(name));
56		}
57	
58		private @Nullable ConfigurationProperty findConfigurationProperty(String name) {
59			try {
60				return findConfigurationProperty(ConfigurationPropertyName.of(name, true));
61			}
62			catch (Exception ex) {
63				return null;
64			}
65		}
66	
67		@Nullable ConfigurationProperty findConfigurationProperty(@Nullable ConfigurationPropertyName name) {
68			if (name == null) {
69				return null;
70			}
71			for (ConfigurationPropertySource configurationPropertySource : getSource()) {
